{"content": "package ledger

import "context"

func (l *Ledger) Transfer(ctx context.Context, id, from, to string, amount int64) (Receipt, error) {
	if err := ctx.Err(); err != nil {
		return Receipt{}, err
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return Receipt{}, err
	}
	if id == "" || amount <= 0 || from == to {
		return Receipt{}, ErrInvalid
	}
	if _, ok := l.balances[from]; !ok {
		return Receipt{}, ErrMissingAccount
	}
	if _, ok := l.balances[to]; !ok {
		return Receipt{}, ErrMissingAccount
	}
	if existing, ok := l.receipts[id]; ok {
		if existing.From == from && existing.To == to && existing.Amount == amount {
			return existing, nil
		}
		return Receipt{}, ErrConflict
	}
	if l.balances[from] < amount {
		return Receipt{}, ErrInsufficientFunds
	}
	l.balances[from] -= amount
	l.balances[to] += amount
	r := Receipt{ID: id, From: from, To: to, Amount: amount,
		FromBalance: l.balances[from], ToBalance: l.balances[to]}
	l.receipts[id] = r
	return r, nil
}
