{"content": "package ledger

import (
	"context"
	"errors"
	"sync"
	"testing"
)

func TestTransferOne(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	got, err := book.Transfer(context.Background(), "tx-1", "a", "b", 3)
	if err != nil || got.FromBalance != 7 || got.ToBalance != 3 {
		t.Fatalf("receipt=%+v error=%v", got, err)
	}
}

func TestTransferValidation(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 5})
	ctx := context.Background()
	if _, err := book.Transfer(ctx, "", "a", "b", 1); !errors.Is(err, ErrInvalid) {
		t.Fatalf("empty id: %v", err)
	}
	if _, err := book.Transfer(ctx, "x", "a", "a", 1); !errors.Is(err, ErrInvalid) {
		t.Fatalf("same account: %v", err)
	}
	if _, err := book.Transfer(ctx, "x", "a", "b", 0); !errors.Is(err, ErrInvalid) {
		t.Fatalf("zero amount: %v", err)
	}
	if _, err := book.Transfer(ctx, "x", "a", "b", -1); !errors.Is(err, ErrInvalid) {
		t.Fatalf("negative amount: %v", err)
	}
	if _, err := book.Transfer(ctx, "x", "missing", "b", 1); !errors.Is(err, ErrMissingAccount) {
		t.Fatalf("missing from: %v", err)
	}
	if _, err := book.Transfer(ctx, "x", "a", "missing", 1); !errors.Is(err, ErrMissingAccount) {
		t.Fatalf("missing to: %v", err)
	}
}

func TestTransferInsufficientFundsNoMutation(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 5, "b": 0})
	if _, err := book.Transfer(context.Background(), "tx", "a", "b", 6); !errors.Is(err, ErrInsufficientFunds) {
		t.Fatalf("err=%v", err)
	}
	if bal, _ := book.Balance("a"); bal != 5 {
		t.Fatalf("a=%d", bal)
	}
	if bal, _ := book.Balance("b"); bal != 0 {
		t.Fatalf("b=%d", bal)
	}
}

func TestTransferRetryIdempotent(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	ctx := context.Background()
	r1, err := book.Transfer(ctx, "tx", "a", "b", 4)
	if err != nil {
		t.Fatal(err)
	}
	r2, err := book.Transfer(ctx, "tx", "a", "b", 4)
	if err != nil {
		t.Fatal(err)
	}
	if r1 != r2 {
		t.Fatalf("r1=%+v r2=%+v", r1, r2)
	}
	if bal, _ := book.Balance("a"); bal != 6 {
		t.Fatalf("a=%d", bal)
	}
	if bal, _ := book.Balance("b"); bal != 4 {
		t.Fatalf("b=%d", bal)
	}
}

func TestTransferConflict(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0, "c": 0})
	ctx := context.Background()
	if _, err := book.Transfer(ctx, "tx", "a", "b", 4); err != nil {
		t.Fatal(err)
	}
	if _, err := book.Transfer(ctx, "tx", "a", "c", 4); !errors.Is(err, ErrConflict) {
		t.Fatalf("err=%v", err)
	}
	if _, err := book.Transfer(ctx, "tx", "a", "b", 5); !errors.Is(err, ErrConflict) {
		t.Fatalf("err=%v", err)
	}
}

func TestTransferCancelledContext(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := book.Transfer(ctx, "tx", "a", "b", 4); err == nil {
		t.Fatal("expected error")
	}
	if bal, _ := book.Balance("a"); bal != 10 {
		t.Fatalf("a=%d", bal)
	}
	if bal, _ := book.Balance("b"); bal != 0 {
		t.Fatalf("b=%d", bal)
	}
}

func TestTransferConcurrent(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 1000, "b": 0})
	ctx := context.Background()
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			_, _ = book.Transfer(ctx, "shared", "a", "b", 1)
		}(i)
	}
	wg.Wait()
	if bal, _ := book.Balance("a"); bal != 999 {
		t.Fatalf("a=%d", bal)
	}
	if bal, _ := book.Balance("b"); bal != 1 {
		t.Fatalf("b=%d", bal)
	}

	// Distinct IDs concurrently: balances must be consistent.
	book2 := NewLedger(map[string]int64{"a": 1000, "b": 0})
	var wg2 sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg2.Add(1)
		go func(i int) {
			defer wg2.Done()
			_, _ = book2.Transfer(ctx, "id-"+string(rune('0'+i%10))+"-"+string(rune('a'+i/10)), "a", "b", 1)
		}(i)
	}
	wg2.Wait()
	a, _ := book2.Balance("a")
	b, _ := book2.Balance("b")
	if a+b != 1000 {
		t.Fatalf("a=%d b=%d", a, b)
	}
}
